# Content for the A level NEA stage introductions (Pearson Edexcel 9DT0/02, assessment grids 1 to 11, 120 marks).
# Worked example throughout: the practice context "Inclusive living" and an invented client, Ruth (78), whose
# arthritis makes opening jars and bottles painful. Blocks are placed on a 1600 x 1131 A3 sheet.

CLIENT = 'Example project: Ruth, 78, weak grip from arthritis'
C = 'Folder'

def D(**k):
    k.setdefault('bands', [('Lower', 'descriptive, generic, little justification'), ('Middle', 'relevant and partly justified'), ('Top', 'sophisticated, client-led, fully justified')])
    return k

